/bin/bash -lc "python - <<'PY'
from desk.label_ellipsis import truncate_label

for value in ('', 'a', 'abcd', '🙂é漢字', 'e\\u0301xyz'):
    for limit in range(7):
        result = truncate_label(value, limit)
        assert len(result) <= limit, (value, limit, result)
        assert result == (value if len(value) <= limit else value[:limit - 1] + '…' if limit else '')
for limit in (-1, 1.5, True, None, '2'):
    try:
        truncate_label('abc', limit)
    except ValueError:
        pass
    else:
        raise AssertionError(limit)
print('Boundary, Unicode, and invalid-limit checks passed.')
PY
 git diff --check
 git diff -- desk/label_ellipsis.py"

